package com.realmsoffate.toolkit.ui.magic;
import com.realmsoffate.toolkit.data.SpellLibraryService;import com.realmsoffate.toolkit.project.ModProject;import javax.swing.*;import java.awt.*;import java.io.IOException;import java.util.List;
public class SpellPickerDialog extends JDialog{
 private SpellLibraryService.SpellDefinition selection;
 public SpellPickerDialog(Window owner,ModProject project){super(owner,"Choose Spell",ModalityType.APPLICATION_MODAL);setSize(560,500);setLocationRelativeTo(owner);setLayout(new BorderLayout(10,10));JPanel list=new JPanel();list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));try{List<SpellLibraryService.SpellDefinition> spells=new SpellLibraryService().list(project);if(spells.isEmpty())list.add(new JLabel("No reusable spells exist yet. Create one from Magic first."));for(SpellLibraryService.SpellDefinition s:spells){JButton b=new JButton("<html><b>"+escape(s.getName())+"</b><br><small>"+escape(shortClass(s.getClassName()))+"</small></html>");b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,58));b.addActionListener(e->{selection=s;dispose();});list.add(b);list.add(Box.createVerticalStrut(6));}}catch(IOException ex){list.add(new JLabel(ex.getMessage()));}JScrollPane sp=new JScrollPane(list);sp.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));JButton cancel=new JButton("Cancel");cancel.addActionListener(e->dispose());JPanel bottom=new JPanel(new FlowLayout(FlowLayout.RIGHT));bottom.add(cancel);add(sp,BorderLayout.CENTER);add(bottom,BorderLayout.SOUTH);}
 public SpellLibraryService.SpellDefinition getSelection(){return selection;}private String shortClass(String c){int i=c.lastIndexOf('.');return i>=0?c.substring(i+1):c;}private String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
}
